def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    ink = next(v for row in grid for v in row if v != bg)
    out = [row[:] for row in grid]

    def qualifies(coords):
        runs = 0
        prev = -2
        for x in coords:
            if x > prev + 1:
                runs += 1
            prev = x
        return len(coords) >= 4 or runs >= 3

    for r in range(h):
        xs = [c for c in range(w) if grid[r][c] == ink]
        if xs and qualifies(xs):
            for c in range(xs[0] + 1, xs[-1]):
                if grid[r][c] == bg:
                    out[r][c] = 2
    for c in range(w):
        ys = [r for r in range(h) if grid[r][c] == ink]
        if ys and qualifies(ys):
            for r in range(ys[0] + 1, ys[-1]):
                if grid[r][c] == bg:
                    out[r][c] = 2
    return out

